"""地球2：火をふく大地（ワーク p30〜33・41・44〜45、教科書 p84〜98）"""
from kbank import T, C, SEQ, N, S, R
from sci import unit

MAJ = '火をふく大地'

def kazan():
    u = unit('kazan', '火山の噴火とマグマの性質', MAJ, {30, 31, 33, 41, 44, 45},
             '2026-10-05 Claude作成。理科ワークp30〜31（教科書チェック）・p33基本①と○×①②・p41力だめし①(5)・p44〜45まとめと、教科書p84〜93（火山の噴火・火山噴出物・ためしてみよう・図28〜31・マグマの性質と火山・探Q実験1とその例・図34〜35・なるほど）を写真で確認して作成。')
    q = u.q
    q(30, '①(1)', '活火山', '現在活動している火山や、おおむね過去1万年以内に噴火したことがある火山を何というか。', T('活火山', 'かっかざん'), '教科書p84：現在活動している火山や、おおむね過去1万年以内に噴火したことがある火山を活火山という。', tb=84, tbnote='本文')
    q(30, '①(1)', '活火山', '日本には、活火山がおよそいくつ以上あるか。', N(110, ['以上', 'つ以上']), '教科書p84注❶：日本には110以上の活火山がある。', tb=84, tbnote='注❶', near=['11', '1100'])
    q(30, '①(1)', '活火山', '活火山の定義で、「おおむね過去何年以内に噴火したことがある火山」とされているか。', N(10000, ['年', '年以内', '万年']), '教科書p84：おおむね過去1万年以内に噴火したことがある火山。', tb=84, tbnote='本文', near=['1000', '100000'])
    q(30, '①(2)', '火山噴出物', '火山の噴火によって噴出する溶岩や火山灰などをまとめて何というか。', T('火山噴出物', 'かざんふんしゅつぶつ'), '教科書p84：溶岩や火山灰のほかに、火山弾、軽石、火山れき、火山ガスなどの火山噴出物を噴出する。', tb=84, tbnote='本文', near=['火成岩'])
    q(30, '①(2)', '火山噴出物', '次のうち、火山噴出物をすべて選ぼう。\nア 溶岩　イ 火山灰　ウ 軽石　エ 火山ガス', C('アイウエ'), '教科書p84：溶岩や火山灰、火山弾、軽石、火山れき、火山ガスなどの火山噴出物。', tb=84, tbnote='本文', near=['アイウ', 'アイ'])
    q(30, '①(2)', '火山ガス', '火山ガスのおもな成分は何か。', T('水蒸気', 'すいじょうき'), '教科書p84注❷：火山ガスは、おもに水蒸気で、二酸化炭素や硫化水素などもふくむ。', tb=84, tbnote='注❷', near=['二酸化炭素'])
    q(30, '①(2)', '火山ガス', '火山ガスに、水蒸気のほかにふくまれる気体を2つ答えよう。', S(('二酸化炭素', 'にさんかたんそ'), ('硫化水素', 'りゅうかすいそ')), '教科書p84注❷：二酸化炭素や硫化水素などもふくむ。', tb=84, tbnote='注❷', near=['二酸化炭素'])
    q(30, '①(3)①', '火山灰', '火山れきと火山灰は粒の大きさで区別する。直径何mm以下の粒が火山灰か。', N(2, ['mm', 'ミリ']), '教科書p85：火山れきと火山灰は粒の大きさで区別し、直径2 mm以下の粒が火山灰である。', tb=85, tbnote='本文', near=['1/16', '0.2'])
    q(30, '①(3)②', '軽石', '多孔質（小さな穴がたくさんある状態）で軽く、水に浮くことがある火山噴出物は何か。', T('軽石', 'かるいし'), '教科書p85：軽石は多孔質で軽く、水に浮くことがある。', tb=85, tbnote='本文', near=['火山弾'])
    q(30, '①(3)', '火山弾と軽石', '火山弾と軽石は、何による名称か。', T('形態', 'けいたい', '形', 'かたち', '形態による名称'), '教科書p85：火山弾と軽石は、形態による名称である。', tb=85, tbnote='本文', near=['粒の大きさ'])
    q(30, '①(3)', '火山れきと火山灰', '火山れきと火山灰は、何で区別するか。', T('粒の大きさ', '大きさ', 'つぶの大きさ'), '教科書p85：火山れきと火山灰は粒の大きさで区別する。', tb=85, tbnote='本文', near=['形'])
    q(30, '①(3)', '軽石', '軽石に多数の小さな穴があるのは、なぜか。', R((1, ['火山ガス', 'ガス', '気体']), (1, ['ぬけ', '抜け', '出た', 'でた'])), '教科書p87部活ラボ：軽石の多数の小さな穴は、噴出した溶岩がかたまるときに、溶岩の中の火山ガスが空気中にぬけ出したあとである。', tb=87, tbnote='部活ラボ', example='溶岩がかたまるときに、中の火山ガスがぬけ出したあとだから。')
    q(30, '①(3)', '軽石', '軽石が野球場やサッカー場などで利用されることがあるのは、軽石のどのような性質を生かしているか。', R((1, ['水']), (1, ['たまりにくい', 'たまらない', '水はけ', '吸', 'しみこ'])), '教科書p87部活ラボ：水がたまりにくい軽石の性質を生かし、野球場、サッカー場、陸上競技場、ゴルフ場、テニスコートなどで利用される。', tb=87, tbnote='部活ラボ', example='水がたまりにくい性質')
    q(30, '①(3)', '溶岩', '溶岩とは、地表に出てきた高温の液体状のものだけをいうか。', T('いわない', 'いいえ', 'ちがう', '冷え固まったものもいう'), '教科書p85：溶岩は、地表に出てきた高温の液体状のものだけでなく、冷え固まったものもいう。', tb=85, tbnote='本文', near=['いう'])
    q(30, '①(4)', '火山灰の観察', '火山灰を観察するとき、蒸発皿の火山灰を水で湿らせたあと、何でよくこねるか。', T('親指の腹', '親指', 'おやゆびのはら', '指', '指の腹'), '教科書p85：小さじ1ぱいぐらいの火山灰を蒸発皿に入れ、水で湿らせ、親指の腹でよくこねる。', tb=85, tbnote='火山灰の観察', near=['ガラス棒'])
    q(30, '①(5)', '火山灰の観察', '火山灰に水を加えてかき混ぜ、にごった水を捨てる。これを水がどうなるまでくり返すか。', R((1, ['にごらな', '濁らな', 'にごりがなく', '透明', 'すきとお'])), '教科書p85：ごみやよごれを洗い流すため、水がにごらなくなるまで②〜④をくり返す。', tb=85, tbnote='火山灰の観察', example='水がにごらなくなるまで')
    q(30, '①(6)', '火山灰の観察', '乾燥させた火山灰から、磁石を薬包紙に包んで引きつけて除く粒は、おもに何という鉱物か。', T('磁鉄鉱', 'じてっこう'), '教科書p85ポイント：磁石に引きつけられた粒はおもに磁鉄鉱である。', tb=85, tbnote='ポイント', near=['カンラン石'])
    q(30, '①(6)', '火山灰の観察', '洗った火山灰は、双眼実体顕微鏡で何倍程度に拡大して観察するか。「〇〜〇倍」の形で答えよう。', T('20〜40倍', '20〜40', '20~40倍', '20から40倍', '20倍〜40倍'), '教科書p85：双眼実体顕微鏡で20〜40倍に拡大して観察する。', tb=85, tbnote='火山灰の観察')
    q(30, '①(6)', '火山灰', '火山灰の粒は、丸みを帯びたものと角ばったもののどちらが多いか（小学校6年で学習）。', T('角ばったもの', '角ばった', 'かどばった', '角張ったもの', '角ばっている'), '教科書p84つながる学び（小6）：火山灰は角ばったものが多い。', tb=84, tbnote='つながる学び', near=['丸みを帯びたもの'])
    q(30, '②(1)', 'マグマ', '地下深いところの岩石の一部が、高温などのためにどろどろにとけたものを何というか。', T('マグマ', 'まぐま'), '教科書p86：どの火山噴出物も、地下深いところの岩石の一部が、高温などのためにどろどろにとけたマグマからできたものである。', tb=86, tbnote='本文', near=['溶岩'])
    q(30, '②(2)', 'マグマだまり', '上昇してきたマグマが、地下に一時的に停止してたまっているところを何というか。', T('マグマだまり', 'まぐまだまり'), '教科書p86：地下10 kmくらいか、それよりも浅いところまで上昇したマグマは、一時的に停止してたまっていく。このようにしてマグマだまりができる。', tb=86, tbnote='図28', near=['火口'])
    q(30, '②(2)', 'マグマ', '日本の火山をつくるマグマの多くは、海洋プレートが地下約何kmの深さまで沈みこんだところの上方でできるか。「約〇〜〇km」の形で答えよう。', T('約100〜150km', '100〜150km', '100〜150', '約100〜150 km', '100~150km', '100から150km'), '教科書p86：海洋プレートが地下約100〜150 kmの深さまで沈みこんだところの上方でできて、上昇する。', tb=86, tbnote='本文')
    q(30, '②(2)', 'マグマだまり', 'マグマだまりは、地下何kmくらいか、それよりも浅いところにできるか。', N(10, ['km', 'キロメートル']), '教科書p86：やがて、地下10 kmくらいか、それよりも浅いところまで上昇したマグマは、一時的に停止してたまっていく。', tb=86, tbnote='本文', near=['100', '1'])
    q(30, '②(3)', '鉱物', 'マグマが冷えてできる、一定の形や色をした結晶を何というか。', T('鉱物', 'こうぶつ'), '教科書p86：マグマだまりなどでマグマが冷えはじめると、鉱物とよばれる一定の形や色をした結晶ができたりする。', tb=86, tbnote='本文', near=['火成岩'])
    q(30, '②(5)', '噴火のしくみ', '多くの泡が現れて膨張したマグマは、何が小さくなって上昇しやすくなるか。', T('密度', 'みつど'), '教科書p87：多くの泡が現れて膨張したマグマは、密度が小さくなって上昇しやすくなり、大地の割れ目を通るなどして地表に噴出する。', tb=87, tbnote='本文', near=['質量', '体積'])
    q(30, '②(5)', '噴火のしくみ', 'マグマが冷えはじめると、マグマにとけこみにくくなった気体（おもに水蒸気）はどうなるか。', R((1, ['泡', 'あわ'])), '教科書p86：マグマにとけこみにくくなった気体（おもに水蒸気）が泡として現れたりする。', tb=86, tbnote='本文', example='泡として現れる。')
    q(30, '②(5)', '噴火のしくみ', '膨張したマグマが上昇し、大地の割れ目を通るなどして地表に噴出すると、何が起こるか。', T('噴火', 'ふんか'), 'ワークp30②(5)：噴火が起こる。教科書p87：大地の割れ目を通るなどして地表に噴出する。', tb=87, tbnote='本文')
    q(30, '②(5)', '噴火のしくみ', 'マグマの噴出とよく似ているとして教科書の図31で示されている身近な現象は何か。', T('炭酸水の発泡', '炭酸水', 'たんさんすい', '炭酸水のあわ'), '教科書p87図31：炭酸水の発泡（図31は、マグマの噴出とよく似ている）。', tb=87, tbnote='図31')
    q(30, '②(5)', '火山ガラス', 'マグマが急に冷えるなどして結晶にならなかったものを何というか。', T('火山ガラス', 'かざんガラス'), '教科書p87図30：火山ガラスは、マグマが急に冷えるなどして結晶にならなかったものである。', tb=87, tbnote='図30', near=['鉱物'])
    q(30, '②(6)', 'マグマの性質', '火山によって、火山噴出物の特徴や噴火のようすがちがうのは、何のちがいによるか。', T('マグマの性質', 'マグマのせいしつ', 'マグマの性質のちがい'), '教科書p87：火山によって火山噴出物の特徴、噴火のようすはちがう。これは、マグマの性質のちがいによるものである。', tb=87, tbnote='本文', near=['火山の大きさ'])
    q(31, '①(4)', 'ねばりけ', '探Q実験1から、マグマのどのような性質のちがいが、火山の形に関係していると考えられるか。', R((1, ['ねばりけ', '粘り気', '流れにく', '流れやす'])), '教科書p92：マグマの流れにくさ（ねばりけ）のちがいが、火山の形のちがいに関係していることがわかった。', tb=92, tbnote='探Q実験1から', example='マグマのねばりけ（流れにくさ）')
    q(31, '①(2)', 'ねばりけ', '探Q実験1で、ねばりけが小さい物質アと大きい物質イをポリエチレンの袋から押し出した。流れやすかったのはどちらか。', T('ア', '物質ア'), 'ワークp31①(2)：ねばりけが小さい物質アのほうが流れやすい。', tb=90, tbnote='探Q実験1の例', near=['イ'])
    q(31, '①(3)', 'ねばりけ', '同じ実験で、傾斜が急で盛り上がった形になったのは物質ア・イのどちらか。', T('イ', '物質イ'), 'ワークp31①(3)②：ねばりけが大きい物質イは、流れにくく、傾斜が急で盛り上がった形になる。', tb=92, tbnote='図35', near=['ア'])
    q(31, '①(1)', 'ねばりけ', '探Q実験1で、ポリエチレンの袋に入れた物質ア・イは、火山の何に対応しているか。', T('マグマ', 'まぐま'), 'ワークp31①(1)：物質はマグマに対応している（教科書p89：ポリエチレンの袋内の物質は、マグマに対応している）。', tb=89, tbnote='吹き出し', near=['溶岩'])
    q(31, '①(1)', 'ねばりけ', '探Q実験1の例Aで、ねばりけのちがう物質をつくるのに使う歯科用の材料は何か。', T('型どり剤', '型取り剤', 'かたどりざい', 'アルギン酸塩印象材'), '教科書p90：A 歯科で用いる型どり剤（アルギン酸塩印象材）を用いる方法。', tb=90, tbnote='A')
