    q(32, '①(1)', '火成岩', '火成岩には、組織のほかに何のちがいがあるか（教科書の注）。2つ答えよう。', S(('鉱物の種類', '種類'), ('割合', 'わりあい', '鉱物の割合')), '教科書p96注❶：火成岩は組織のほかに、鉱物の種類や割合などがちがう。', tb=96, tbnote='注❶', near=['鉱物の種類'])
